mapper.select:
SELECT po.id AS orderId, po.order_no AS orderNo, po.supplier_id AS supplierId, s.name AS supplierName, po.create_time AS orderTime, poi.quantity AS quantity, poi.price AS price FROM purchase_order_item poi JOIN purchase_order po ON po.id = poi.order_id JOIN supplier s ON s.id = po.supplier_id WHERE poi.goods_id = #{goodsId} AND po.status NOT IN ('DRAFT', 'CANCELLED', 'TERMINATED')
AND po.create_time >= #{beginTime}
AND po.create_time < #{endTime}
ORDER BY po.create_time, po.id

